const gearOwned = (id) => !!(settings.gear && settings.gear[id] === true);
const gearOk = (e) => !e.gear || e.gear.some(gearOwned);
const gearName = (id) => { const g = GEAR.find((x) => x.id === id); return g ? g.name : id; };
const gearNames = (e) => (e.gear || []).map(gearName).join(" oder ");
const lockedVariants = (slot) => EXALL.filter((x) => x.slot === slot && !gearOk(x));
const EXBASE = EX.slice();
const EXALL = EXBASE.concat(EXALT, EXFUT);
const exById = (id) => EXALL.find((x) => x.id === id);
const slotVariants = (slot) => EXALL.filter((x) => x.slot === slot && gearOk(x));
const SLOTNAME = { squat: "Beine", push: "Brust", row: "Rücken (Rudern)", pike: "Schultern", bridge: "Po und Hüfte", plank: "Rumpf" };
let SWAPD = { date: "", map: {} };
function altFor(slot) {
  const t = SWAPD.date === todayISO() ? SWAPD.map[slot] : null, perm = settings.alt && typeof settings.alt === "object" ? settings.alt[slot] : null;
  const ok = (id) => id && exById(id) && exById(id).slot === slot && gearOk(exById(id));
  return ok(t) ? t : ok(perm) ? perm : slot;
}
function applyAlts() { EXBASE.forEach((b, i) => { EX[i] = exById(altFor(b.slot)); }); }

